const raw = $json.text || "";

const clean = raw
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

const data = JSON.parse(clean);

const skills = (data.matched_skills || [])
  .map(skill => `
    <span style="
      display:inline-block;
      box-sizing:border-box;
      max-width:100%;
      background:#eef6ff;
      color:#1d4ed8;
      border:1px solid #dbeafe;
      padding:7px 11px;
      margin:4px 3px;
      border-radius:20px;
      font-size:13px;
      font-weight:600;
      line-height:1.35;
      white-space:normal;
      overflow-wrap:anywhere;
      word-break:break-word;
    ">${skill}</span>
  `)
  .join("");

const gaps = (data.missing_skills || [])
  .map(skill => `
    <li style="
      margin:7px 0;
      line-height:1.5;
      overflow-wrap:anywhere;
      word-break:break-word;
    ">${skill}</li>
  `)
  .join("");

const score = Number(data.score || 0);

let scoreColor = "#16a34a";
let scoreBg = "#dcfce7";

if (score < 60) {
  scoreColor = "#dc2626";
  scoreBg = "#fee2e2";
} else if (score < 80) {
  scoreColor = "#d97706";
  scoreBg = "#fef3c7";
}

const html = `
<div style="
  width:100%;
  max-width:760px;
  box-sizing:border-box;
  margin:0 auto;
  padding:10px 16px 30px;
  font-family:Arial,Helvetica,sans-serif;
  color:#1f2937;
  overflow:hidden;
">

  <!-- Score Card -->
  <div style="
    width:100%;
    box-sizing:border-box;
    background:linear-gradient(135deg,#111827,#26364a);
    color:white;
    border-radius:18px;
    padding:28px 20px;
    text-align:center;
    margin-bottom:18px;
  ">

    <div style="
      font-size:14px;
      font-weight:600;
      letter-spacing:1px;
      text-transform:uppercase;
      opacity:.8;
    ">
      Resume Match
    </div>

    <div style="
      font-size:58px;
      font-weight:800;
      line-height:1;
      margin:14px 0 10px;
      color:#34d399;
    ">
      ${score}%
    </div>

    <div style="
      display:inline-block;
      background:${scoreBg};
      color:${scoreColor};
      padding:7px 16px;
      border-radius:30px;
      font-size:13px;
      font-weight:700;
    ">
      ${data.verdict || "Match"}
    </div>

  </div>


  <!-- Matching Skills -->
  <div style="
    width:100%;
    box-sizing:border-box;
    background:#ffffff;
    border:1px solid #e5e7eb;
    border-radius:15px;
    padding:20px;
    margin-bottom:16px;
  ">

    <div style="
      font-size:18px;
      font-weight:700;
      margin-bottom:14px;
      color:#111827;
    ">
      <span style="color:#16a34a;">✓</span>
      Matching Skills
    </div>

    <div style="
      width:100%;
      box-sizing:border-box;
      display:flex;
      flex-wrap:wrap;
      align-items:flex-start;
      justify-content:flex-start;
      gap:2px;
      overflow:hidden;
    ">
      ${skills || "<span>No matching skills found.</span>"}
    </div>

  </div>


  <!-- Skill Gaps -->
  <div style="
    width:100%;
    box-sizing:border-box;
    background:#fffaf0;
    border:1px solid #fde68a;
    border-radius:15px;
    padding:20px;
    margin-bottom:16px;
  ">

    <div style="
      font-size:18px;
      font-weight:700;
      color:#92400e;
      margin-bottom:12px;
    ">
      <span>⚠</span>
      Skill Gaps
    </div>

    <ul style="
      margin:0;
      padding-left:22px;
      color:#78350f;
    ">
      ${gaps || "<li>No major skill gaps identified.</li>"}
    </ul>

  </div>


  <!-- Recruiter Summary -->
  <div style="
    width:100%;
    box-sizing:border-box;
    background:#ffffff;
    border:1px solid #e5e7eb;
    border-radius:15px;
    padding:20px;
  ">

    <div style="
      font-size:18px;
      font-weight:700;
      color:#111827;
      margin-bottom:12px;
    ">
      <span>📋</span>
      Recruiter Summary
    </div>

    <div style="
      font-size:14px;
      line-height:1.7;
      color:#4b5563;
      overflow-wrap:anywhere;
      word-break:break-word;
    ">
      ${data.summary || "No summary available."}
    </div>

  </div>

</div>
`;

return [
  {
    json: {
      html
    }
  }
];

parameters.jsCode:
const raw = $json.text || "";

const clean = raw
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

const data = JSON.parse(clean);

const skills = (data.matched_skills || [])
  .map(skill => `
    <span style="
      display:inline-block;
      background:#e8f5ee;
      color:#166534;
      padding:8px 12px;
      margin:4px;
      border-radius:20px;
      font-size:14px;
      font-weight:600;
    ">${skill}</span>
  `)
  .join("");

const gaps = (data.missing_skills || [])
  .map(skill => `
    <li style="
      margin:8px 0;
      color:#374151;
    ">${skill}</li>
  `)
  .join("");

const score = Number(data.score || 0);

let scoreBackground = "#16a34a";

if (score < 60) {
  scoreBackground = "#dc2626";
} else if (score < 80) {
  scoreBackground = "#f59e0b";
}

const html = `
<div style="
  font-family:Arial,Helvetica,sans-serif;
  max-width:850px;
  margin:20px auto;
  color:#172033;
">

  <!-- HEADER -->
  <div style="
    background:linear-gradient(135deg,#111827,#243b53);
    color:white;
    padding:35px 25px;
    border-radius:18px;
    text-align:center;
    margin-bottom:20px;
  ">

    <div style="
      font-size:24px;
      font-weight:700;
      margin-bottom:18px;
    ">
      Resume Match Report
    </div>

    <div style="
      font-size:64px;
      font-weight:800;
      line-height:1;
      margin:15px 0;
    ">
      ${score}%
    </div>

    <div style="
      display:inline-block;
      background:${scoreBackground};
      color:white;
      padding:8px 18px;
      border-radius:20px;
      font-size:14px;
      font-weight:700;
    ">
      ${data.verdict || "Match"}
    </div>

  </div>


  <!-- MATCHING SKILLS -->
  <div style="
    background:white;
    border:1px solid #e5e7eb;
    border-radius:16px;
    padding:24px;
    margin-bottom:18px;
  ">

    <h2 style="
      margin:0 0 18px 0;
      font-size:19px;
      color:#166534;
    ">
      ✅ Matching Skills
    </h2>

    <div>
      ${skills || "<p>No matching skills found.</p>"}
    </div>

  </div>


  <!-- SKILL GAPS -->
  <div style="
    background:white;
    border:1px solid #e5e7eb;
    border-radius:16px;
    padding:24px;
    margin-bottom:18px;
  ">

    <h2 style="
      margin:0 0 15px 0;
      font-size:19px;
      color:#b45309;
    ">
      ⚠️ Skill Gaps
    </h2>

    <ul style="
      padding-left:22px;
      margin:0;
    ">
      ${
        gaps ||
        "<li>No major skill gaps identified.</li>"
      }
    </ul>

  </div>


  <!-- SUMMARY -->
  <div style="
    background:white;
    border:1px solid #e5e7eb;
    border-radius:16px;
    padding:24px;
    margin-bottom:18px;
  ">

    <h2 style="
      margin:0 0 15px 0;
      font-size:19px;
      color:#172033;
    ">
      📋 Recruiter Summary
    </h2>

    <p style="
      line-height:1.7;
      color:#4b5563;
      margin:0;
    ">
      ${data.summary || "No summary available."}
    </p>

  </div>

</div>
`;

return [
  {
    json: {
      html
    }
  }
];
